9: export function directoryBrowser(root) {
10:   const listing = serveIndex(root, { icons: true, view: 'details' })
11:   return {
12:     name: 'omgithub-directory-browser',
13:     configureServer(server) {
14:       server.middlewares.use(async (req, res, next) => {
15:         if (req.method !== 'GET' && req.method !== 'HEAD') return next()
16:         try {
17:           const url = new URL(req.url, 'http://localhost')
18:           const file = resolve(root, '.' + decodeURIComponent(url.pathname))
19:           const within = relative(root, file)
20:           if (within.startsWith('..') || isAbsolute(within)) return next()
21:           const info = await stat(file)
22:           res.setHeader('Cache-Control', 'no-cache')
23:           if (info.isDirectory()) {
24:             if (!url.pathname.endsWith('/')) {
25:               res.writeHead(302, { Location: url.pathname + '/' + url.search }); res.end(); return
26:             }
27:             return listing(req, res, next)
28:           }
29:           // Keep document/source browsing readable; leave browser modules to Vite.
30:           if (textExtensions.has(extname(file)) && !url.searchParams.has('import') && !url.searchParams.has('raw')) {
31:             res.setHeader('Content-Type', 'text/plain; charset=utf-8')
32:             res.end(req.method === 'HEAD' ? undefined : await readFile(file)); return
33:           }
34:           next()
35:         } catch (error) {
36:           if (error.code === 'ENOENT' || error.code === 'ENOTDIR') return next()
37:           next(error)
38:         }
39:       })
40:     }
41:   }
42: }
