44: export async function startLiveFiles({ root, port = 0, cacheDir, allowedHosts = [] } = {}) {
45:   root = resolve(root)
46:   const server = await createServer({
47:     // Start before the agent creates package.json/config/dependencies. Keep this
48:     // managed source browser independent of project build and startup scripts.
49:     configFile: false,
50:     root,
51:     base: '/',
52:     appType: 'mpa',
53:     cacheDir,
54:     plugins: [directoryBrowser(root)],
55:     server: {
56:       host: '127.0.0.1', port, strictPort: true,
57:       allowedHosts,
58:       headers: { 'Cache-Control': 'no-cache' }
59:     }
60:   })
61:   await server.listen()
62:   return server
63: }
64: 
65: if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
66:   const started = performance.now()
67:   const server = await startLiveFiles({
68:     root: process.env.PROJECT_DIR,
69:     port: Number(process.env.PROJECT_FILE_PORT),
70:     cacheDir: join(process.env.OPENCODE_WEB_DIR, 'live-vite-cache'),
71:     allowedHosts: ['.omgithub.com', '.lolgames.net']
72:   })
73:   console.error(`[timing] live source server startup: ${Math.round(performance.now() - started)} ms`)
74:   server.printUrls()
75:   for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, async () => { await server.close(); process.exit(0) })
76: }

